    hamburger.setAttribute('aria-expanded', open);
  });

  // Donation amount tabs
  const tabs = document.querySelectorAll('.amount-tab');
  const descEl = document.getElementById('donation-desc');
  const sublabel = document.querySelector('.donate-sublabel');
  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      tabs.forEach(t => { t.classList.remove('active'); t.setAttribute('aria-pressed', 'false'); });
      tab.classList.add('active');
      tab.setAttribute('aria-pressed', 'true');
      descEl.style.opacity = '0';
      setTimeout(() => {
        descEl.innerHTML = tab.dataset.desc;
        descEl.style.opacity = '1';
      }, 120);
      sublabel.innerHTML = `Donating $${tab.dataset.amount} / month &nbsp;·&nbsp; <a href="#">edit amount</a> &nbsp;·&nbsp; 🔒 Secure donation`;
    });
  });

  // FAQ accordion
  document.getElementById('faq-list').addEventListener('click', e => {
    const btn = e.target.closest('.faq-question');
    if (!btn) return;
    const item = btn.closest('.faq-item');
    const isOpen = item.classList.contains('open');
    // Close all
    document.querySelectorAll('.faq-item.open').forEach(el => el.classList.remove('open'));
    // Toggle clicked
    if (!isOpen) item.classList.add('open');
  });
